// Лаб. 2, п. 2.8. Коннов, СДП-241 ИИ: GET /api/items и GET /api/items/:id
const ITEMS = [
    { id: 1, name: "Датчик температуры", category: "sensor" },
    { id: 2, name: "Датчик влажности", category: "sensor" },
    { id: 3, name: "Реле", category: "actuator" },
    { id: 4, name: "Сервопривод", category: "actuator" },
    { id: 5, name: "Шлюз MQTT", category: "gateway" }
];
const MAX_LIMIT = 100; // верхняя граница ?limit, защита от слишком больших выборок
const POSITIVE_INT = /^[1-9][0-9]*$/;

function fail(status, error, message) {
    msg.statusCode = status;
    msg.payload = { error: error, message: message };
    return msg;
}

const params = msg.req.params || {};
const query = msg.req.query || {};

// Ветка 1: путь /api/items/:id
if (params.id !== undefined) {
    if (!POSITIVE_INT.test(params.id)) {
        return fail(400, "Bad Request", "id должен быть положительным целым числом, получено: " + params.id);
    }
    const found = ITEMS.find(function (it) { return it.id === Number(params.id); });
    if (!found) {
        return fail(404, "Not Found", "элемент с id=" + params.id + " не найден");
    }
    msg.statusCode = 200;
    msg.payload = found;
    return msg;
}

// Ветка 2: список /api/items?limit=N&category=C
let limit = ITEMS.length;
if (query.limit !== undefined) {
    if (typeof query.limit !== "string" || !POSITIVE_INT.test(query.limit) || Number(query.limit) > MAX_LIMIT) {
        return fail(400, "Bad Request", "limit должен быть целым числом от 1 до " + MAX_LIMIT);
    }
    limit = Number(query.limit);
}

let result = [];
for (let i = 0; i < ITEMS.length; i++) {
    if (query.category !== undefined && ITEMS[i].category !== query.category) {
        continue;
    }
    if (result.length >= limit) {
        break;
    }
    result.push(ITEMS[i]);
}

msg.statusCode = 200;
msg.payload = { count: result.length, items: result };
return msg;
